828: /* ============================================================
829:    PHYSICS
830: ============================================================ */
831: function controls() {
832:   return {
833:     throttle: !!(keys['w'] || keys['arrowup'] || virtual.throttle),
834:     brake: !!(keys['s'] || keys['arrowdown'] || virtual.brake || keys[' ']),
835:     steer: (keys['a'] || keys['arrowleft'] || virtual.left ? 1 : 0) - (keys['d'] || keys['arrowright'] || virtual.right ? 1 : 0),
836:     nitro: !!(keys['shift'] || virtual.nitro),
837:   };
838: }
