1016: function updateRacerState(game, r, dt) {
1017:   const track = game.track;
1018:   const near = track.nearest(r.pos, r.hintIdx);
1019:   const prevIdx = r.lastIdx;
1020:   const N = track.count;
1021:   // detect crossing the start line
1022:   if (game.phase === 'racing') {
1023:     if (prevIdx > N * 0.72 && near.idx < N * 0.28) {
1024:       r.crossings++;
1025:       onLapCross(game, r);
1026:     } else if (prevIdx < N * 0.28 && near.idx > N * 0.72) {
1027:       r.crossings--;
1028:     }
1029:   }
1030:   r.hintIdx = near.idx;
1031:   r.lastIdx = near.idx;
1032:   r.lateral = near.lateral;
1033:   r.progress = (r.crossings - 1) * track.length + near.s;
1034:   r.offroad = Math.abs(near.lateral) > track.halfWidth;
1035:   r.visual.root.position.set(r.pos.x, 0.02, r.pos.z);
1036:   r.visual.root.rotation.y = r.yaw;
1037:   const bob = Math.sin(game.time * 24 + r.phase) * 0.004 * clamp(r.speed / 40, 0, 1);
1038:   r.visual.setPose(r.lean, r.pitch, bob);
1039:   r.visual.setBoost(!!r.boost || (r.isPlayer && game.player.boost), game.time);
1040:   // name tags
1041:   if (r.visual.tag) {
1042:     const d = r.pos.distanceTo(game.player.pos);
1043:     const camD = r.pos.distanceTo(state.camera.position);
1044:     const vis = d < 52 && camD > 7.5 && !r.isPlayer;
1045:     r.visual.setTagVisible(vis);
1046:     if (vis) {
1047:       const near = clamp((camD - 7.5) / 6, 0, 1);
1048:       r.visual.setTagOpacity(clamp((52 - d) / 24, 0, 0.72) * near);
1049:     }
1050:   }
1051: }
1052: 
1053: function onLapCross(game, r) {
1054:   const track = game.track;
1055:   if (r.crossings <= 0) return;
1056:   if (r.isPlayer) {
1057:     if (r.crossings === 1) {
1058:       r.lapStart = game.raceTime;
1059:     } else {
1060:       const lap = game.raceTime - r.lapStart;
1061:       r.lapStart = game.raceTime;
1062:       r.lapTimes.push(lap);
1063:       if (lap < r.bestLap) r.bestLap = lap;
1064:       $('lastLap').textContent = `ПОСЛ. ${fmtTime(lap)}`;
1065:       $('bestLap').textContent = `ЛУЧШ. ${fmtTime(r.bestLap)}`;
1066:       state.audio.blip(820, 0.08, 'square', 0.09);
1067:     }
1068:     if (r.crossings >= 2 && r.crossings === game.round.laps) {
1069:       triggerBanner('ПОСЛЕДНИЙ КРУГ');
1070:       state.audio.blip(500, 0.18, 'sawtooth', 0.12);
1071:     } else if (r.crossings >= 2 && r.crossings < game.round.laps) {
1072:       triggerBanner(`КРУГ ${r.crossings}`);
1073:       state.audio.blip(620, 0.12, 'square', 0.1);
1074:     }
1075:     if (r.crossings === game.round.laps + 1) {
1076:       r.finished = true;
1077:       r.finishTime = game.raceTime;
1078:       r.boost = false;
1079:       game.player.boost = false;
1080:       triggerBanner('ФИНИШ');
1081:       state.audio.blip(1000, 0.4, 'sawtooth', 0.15);
1082:       game.resultsTimer = 2.2;
1083:     }
1084:   } else {
1085:     if (r.crossings === 1) r.lapStart = game.raceTime;
1086:     if (r.crossings === game.round.laps + 1 && !r.finished) {
1087:       r.finished = true;
1088:       r.finishTime = game.raceTime;
1089:     }
1090:   }
1091: }
